    let mut enemy = test_enemy(EnemyFamily::Ninja, 60 << 16, (17 * 16) << 16, 2);
    enemy.ninja_state = NinjaState::Stealth;
    enemy.on_ground = true;
    let start_x = enemy.x_pos;
    step_ninja(&mut enemy, Some(&grid), None, None, PlayerForm::TheKid);
